import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"22 | 可观测性：如何设计实现消息轨迹功能？","description":"","frontmatter":{},"headers":[{"level":2,"title":"丢消息是怎么回事？","slug":"丢消息是怎么回事","link":"#丢消息是怎么回事","children":[]},{"level":2,"title":"消息的唯一标识","slug":"消息的唯一标识","link":"#消息的唯一标识","children":[]},{"level":2,"title":"消息轨迹的设计应该注意什么？","slug":"消息轨迹的设计应该注意什么","link":"#消息轨迹的设计应该注意什么","children":[]},{"level":2,"title":"消息轨迹的实现方案设计","slug":"消息轨迹的实现方案设计","link":"#消息轨迹的实现方案设计","children":[{"level":3,"title":"客户端轨迹数据记录","slug":"客户端轨迹数据记录","link":"#客户端轨迹数据记录","children":[]},{"level":3,"title":"服务端轨迹数据记录","slug":"服务端轨迹数据记录","link":"#服务端轨迹数据记录","children":[]},{"level":3,"title":"持久存储引擎的选择","slug":"持久存储引擎的选择","link":"#持久存储引擎的选择","children":[]}]},{"level":2,"title":"RabbitMQ 消息轨迹方案设计实操","slug":"rabbitmq-消息轨迹方案设计实操","link":"#rabbitmq-消息轨迹方案设计实操","children":[]},{"level":2,"title":"分享一个大集群的实际案例","slug":"分享一个大集群的实际案例","link":"#分享一个大集群的实际案例","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"上节课思考闭环","slug":"上节课思考闭环","link":"#上节课思考闭环","children":[]}],"relativePath":"深入拆解消息队列47讲/22｜可观测性：如何设计实现消息轨迹功能？.md","filePath":"深入拆解消息队列47讲/22｜可观测性：如何设计实现消息轨迹功能？.md","lastUpdated":1795450178000}'),p={name:"深入拆解消息队列47讲/22｜可观测性：如何设计实现消息轨迹功能？.md"};function s(n,e,r,o,E,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_22-可观测性-如何设计实现消息轨迹功能" tabindex="-1">22 | 可观测性：如何设计实现消息轨迹功能？ <a class="header-anchor" href="#_22-可观测性-如何设计实现消息轨迹功能" aria-label="Permalink to &quot;22 | 可观测性：如何设计实现消息轨迹功能？&quot;">​</a></h1><p>你好，我是文强。</p><p>今天我们讲可观测性的第三部分：跟踪（Traces），在消息队列领域，Traces 通常被称为消息轨迹，意思是消息在系统中的运行轨迹。消息轨迹在业务消息方向是刚需，因为业务消息如果出现丢失，大概率会导致流程异常。</p><p>比如订单的快递运送流程没有正确处理一条订单号的消息，后续就会出现无法跟踪这个订单派送的问题。如果你负责过消息队列基础服务的日常值班，一定会经常接到用户反馈说消息丢了，想让平台查清楚为什么丢了。这个问题，你会怎么排查呢？</p><p>如果想排查清楚，我们首先要搞清楚有没有丢，如果丢了，还要搞清楚是哪一个环节丢的。想弄清楚这两个问题，就必须有消息轨迹的功能。那我们今天就来讲一讲消息轨迹功能怎样设计。</p><h2 id="丢消息是怎么回事" tabindex="-1">丢消息是怎么回事？ <a class="header-anchor" href="#丢消息是怎么回事" aria-label="Permalink to &quot;丢消息是怎么回事？&quot;">​</a></h2><p>到底什么是“丢消息”？你的第一印象是不是服务端把我的消息弄丢了。其实在消息队列里面，丢消息没这么简单。</p><p>从广义上来讲，消息队列的丢消息是指生产了一条消息，但是预期中的消费者却没有消费到这条消息。但是这个过程，不是只有一种服务端弄丢了消息这一个场景。我们结合消息的生命周期，来看看可能有哪些情况。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/1.jpeg" alt=""></a></p><ul><li><p>生产消息失败，生产端把消息写入到服务端时失败了，这时有可能是服务端有异常，也有可能是消息的内容或格式不符合规范，比如太长了。</p></li><li><p>消息设置了延时属性，消息进入了延时队列后，没有在定义的延时时间内出队列，从而没有在特定的时间执行，错过了消息的有效处理时间，被业务抛弃。</p></li><li><p>消息在服务端存储完成后，因为服务端一致性算法（强一致、最终一致）的设定问题，或者异步刷盘、服务端重启、消息截断之类的行为，导致持久化的消息丢失了。</p></li><li><p>一般消息队列的消费模型是根据 Offset 来定位消费位点或者重置消费位置的。如果消费端设置了错误的位点，比如下一条应该消费位点 100 的消息，但消费端因为异常忽略了100，直接从 101 开始消费。从服务端的角度，100 的消息就没有被消费过，而消费者看来，100 的消费就是没被消费到，此时从消费端的视角，消息就是丢失了。</p></li><li><p>当消费端拉到消息后，如果业务处理有异常，经过了多次处理后依旧失败，消息进入了死信队列，除非业务配置了订阅消费死信队列的消息，否则这条消息的生命周期就算结束了。此</p></li><li><p>时消费端还是没有消费到消息，消息可以算丢失了。</p></li></ul><p>所以从生产消费的流程看，消息的生命周期是很长的，只要其中有一步出现问题，从业务角度看，就会出现类似消息丢失的感知。而消息轨迹就是为了还原轨迹，跟踪单条消息的运行周期。</p><p>不过要定位到单条消息生命周期和运行轨迹，我们得先有消息的唯一标识。</p><h2 id="消息的唯一标识" tabindex="-1">消息的唯一标识 <a class="header-anchor" href="#消息的唯一标识" aria-label="Permalink to &quot;消息的唯一标识&quot;">​</a></h2><p>消息的唯一标识，一般是指消息的唯一 ID，和 OpenTelemetry Traces 中的 Trace ID 是同一个东西。</p><p>业界主流消息队列对消息 ID 的实现有两种形式。一种是明确有消息 ID 概念的，一条消息一定会有一个对应的消息 ID，比如 RocketMQ。</p><p>另一种没有明确消息 ID 概念的，会用另外的形式来标识这是一条消息。比如 RabbitMQ 的消息 ID 是 Header 中的一个可选项，不是必传，如果不传就没有消息 ID 的概念。Kafka 唯一标识一条消息，是通过 Topic + Partition + Offset 来实现的，严格意义上来讲，这种没有明确 ID的消息队列，无法唯一标识一条消息队列。</p><p>一条消息的生命周期是从客户端发出来的时候开始算的，所以发送出来的时候，就应该赋予消息一个唯一 ID，这才能真正表达消息的唯一。一旦在服务端赋予唯一 ID，因为客户端可能会重复发送同一条数据，服务端就会认为是两条数据，生成两个 ID。所以，消息 ID 的生成一般是在客户端 SDK 自动生成或者业务手动生成指定的。</p><p>唯一 ID 的生成方式，业界主要有四种。</p><ul><li><p>最简单的就是 UUID，通过各个语言的 UUID 库生成一个唯一的字符串。</p></li><li><p>集中式的 ID 生成方案，通过某个中央引擎，比如 MySQL 自增列、Redis 自增值、ZooKeeper 自增值等机制保证全局唯一。</p></li><li><p>SnowFlake 算法，通过 Twitter 开源的 SnowFlake 算法生成唯一 ID。</p></li><li><p>自定义算法：通过自定义的算法生成唯一的 ID。</p></li></ul><p>在消息队列领域，我们主要用的是后两种，因为消息队列的消息一般很大，几千亿几万亿级别，UUID 有一定概率会重复，集中式的 ID 生成会增加 SDK 复杂度，基本不会用。SnowFlake 算法是一个成熟的算法，拿来即用。自己设计算法，保证不重复也可以，和SnowFlake 的区别只在于是否是一个成熟开源的算法。所以从技术选择来看，我比较倾向于第三种方案，因为经过工业界的验证，并且表现稳定。</p><p>现在有了唯一 ID，我们就可以开始记录消息轨迹了，那在设计消息轨迹实现的时候，应该考虑哪些因素呢？</p><h2 id="消息轨迹的设计应该注意什么" tabindex="-1">消息轨迹的设计应该注意什么？ <a class="header-anchor" href="#消息轨迹的设计应该注意什么" aria-label="Permalink to &quot;消息轨迹的设计应该注意什么？&quot;">​</a></h2><p>从技术实现来看，消息轨迹的设计分为三步：记录、存储、查询。记录指在合适的地方记录轨迹信息，比如生产端消息发出的时间。存储指将这些轨迹信息存储到某个引擎中。查询指要能支持消息查询。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/2.jpeg" alt=""></a></p><p>那在这三步在设计的时候，我们应该注意哪些点呢？</p><p>记录轨迹，核心诉求就是能在合适的地方记录轨迹信息，达到排查问题的效果。关键节点，比如生产端发出消息、生产端接收到服务端的返回、服务端收到消息、进 / 出延时队列、服务端看到消息被消费、消费端记录到消费到消息、消费端记录处理成功 / 失败、消息进入到死信队列等等。</p><p>记录轨迹不能影响主流程的稳定性和性能。首先不能影响性能，比如生产流程正常耗时10ms，记录轨迹就不能花费 5ms，要尽量减少对流程性能的影响，最好是无感知。另外记录消息的方式不能影响主流程的稳定性，因为轨迹是旁路，偶尔丢失轨迹是允许的，但是不能影响到主流程。</p><p>记录之后的存储、查询是强相关的。存储主要是为查询服务的，因为消息轨迹是一个写多读少的模型，我们选择存储引擎，写入性能一定要足够优秀，不然会影响消息轨迹的写入存储，影响轨迹查询的及时性。</p><p>其次从成本角度考虑，虽然现在硬盘和物理机越来越便宜，但是因为消息轨迹对比消息有几倍的放大，比如上面 RabbitMQ 的例子就有 9 倍的放大，在成本结构中存储的成本占比是最大的。所以首先消息轨迹的内容要足够精简，最精简的可以只包含两个字段——消息 ID、时间，就能满足需求（内容格式上节课我们已经讨论了）。</p><p>另外，轨迹存在的意义就是查询，所以引擎要能支持多维度的查询。以 RabbitMQ 为例，因为RabbitMQ 在正常情况下是没有消息 ID 的，一般需要根据时间、Vhost、Exchange、Channel、Connection、Queue 等多个维度复合查询，所以引擎必须支持多维度的查询，不能是 KV 类型的存储引擎。</p><p>但是支持多维度并不意味着越多越好，引擎满足必要的查询需求就可以了，不要有太多额外的能力。因为我们一般会通过索引或某种数据结构的形式来满足查询需求。复杂的查询需求，存储成本就会相应升高。而消息轨迹的查询需求虽然可能多维度，但是场景是固定的，只要设计上能满足这些查询场景就够了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/3.jpeg" alt=""></a></p><h2 id="消息轨迹的实现方案设计" tabindex="-1">消息轨迹的实现方案设计 <a class="header-anchor" href="#消息轨迹的实现方案设计" aria-label="Permalink to &quot;消息轨迹的实现方案设计&quot;">​</a></h2><p>掌握了设计要点，就要用在技术的选型和实现上了。不过光讲知识点可能不好记，我们从一个具体案例开始，假设要设计一个 RabbitMQ 消息轨迹的技术方案。</p><ol><li><p>预计所有集群总节点规模在几百个左右。</p></li><li><p>每个集群主要承载业务消息，消息量不是特别大。</p></li><li><p>集群不需要记录死信队列、延时队列的进出信息，只需要记录生产者、服务端、消费者三者的生产、接收、消费的时间。</p></li><li><p>需要支持多维度的查询条件，比如 Vhost、Exchange、Channel、Connection、Queue、RouteKey 中的一个或多个字段的组合等值查询，同时需要支持 Headers、Body 的模糊查询。</p></li><li><p>成本要求较为宽松，基本不做限制。</p></li></ol><p>对于这样的项目背景，你会怎么设计呢？非常欢迎留言把你的方案分享出来，接下来带着你的思考，我们进入具体的设计方案分析。</p><p>我们讲过消息队列是富客户端的应用，客户端 SDK 需要有较重的逻辑，比如重试、事务、批量发送等等。所以从消息队列的角度看，完整的消息轨迹包含客户端和服务端两个部分。</p><h3 id="客户端轨迹数据记录" tabindex="-1">客户端轨迹数据记录 <a class="header-anchor" href="#客户端轨迹数据记录" aria-label="Permalink to &quot;客户端轨迹数据记录&quot;">​</a></h3><p>客户端的轨迹记录一般有两种实现形式。一种是客户端将轨迹数据写入到本地文件，通过第三方组件采集到轨迹系统；另一种是客户端将轨迹数据通过 Broker 提供的 TCP/HTTP 接口，或者通过内置主题的方式，写入到集群中的某个主题中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/4.jpeg" alt=""></a></p><p>我们使用消息队列一般会用标准 SDK 访问集群，加上客户端部署的方式和位置无法控制，如果用第一种方案，客户端的轨迹数据很难实现统一的采集上报，所以一般会选择第二种方案，在 SDK 中内置轨迹上报的逻辑，记录轨迹信息并发送到服务端。</p><p>TCP/HTTP 服务收到轨迹数据后，需要保存轨迹数据，保存逻辑和服务端轨迹数据的保存是一样的，我们一起看下。</p><h3 id="服务端轨迹数据记录" tabindex="-1">服务端轨迹数据记录 <a class="header-anchor" href="#服务端轨迹数据记录" aria-label="Permalink to &quot;服务端轨迹数据记录&quot;">​</a></h3><p>正常情况下服务端保存轨迹数据，有四种形式：本地文件、内置 Topic、第三方服务、单机维度的存储引擎。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/5.jpeg" alt=""></a></p><ul><li>本地文件</li></ul><p>在链路跟踪或正常的系统架构中，选择本地文件存储，然后采集上报到存储引擎的方式，基本所有的系统都这样用过。</p><p>优点就是使用方便快捷、体系成熟，因为业界的 ELK 体系很成熟，所以数据采集、上报、存储、分析一条流很常用。缺点是链路较长，成本较高，并且每台节点都需要部署 Agent 采集数据，运维相对复杂。</p><ul><li>内置 Topic</li></ul><p>内置 Topic 把轨迹数据发送到消息队列的某个内置主题中，第三方系统消费内置主题中的轨迹数据，写入到持久存储引擎中。</p><p>优点是复用了消息队列内置的缓存能力，不需要依赖第三方存储，存储成本较低，同时也可以通过部署远程的消费者集群（跟分布式指标采集系统的原理一样）来消费轨迹数据，然后存储，避免了单机运维的复杂度。缺点是需要单独开发一个单独服务，去消费轨迹数据并存储，开发成本较高。</p><ul><li>第三方服务</li></ul><p>直接将轨迹数据存入到第三方存储中，是指记录轨迹数据的时候，直接把数据发送到 ES 等第三方系统。</p><p>优点是简单直接，链路较短，运维复杂度较低。缺点是记录轨迹链路的稳定性依赖于第三方系统，很容易因为第三方系统的抖动，导致主链路不稳定。所以这种方式业界用得比较少，但是在一些数据量较小、业务不是特别重要的场景下，还是有人用。</p><ul><li>单机维度的存储引擎</li></ul><p>把轨迹数据直接存储在各个节点上的文件系统，或部署在该节点上独立的存储服务中。</p><p>优点是链路很短，成本很低，不需要额外的比如 Kafka、Elasticsearch 的成本。缺点是查询麻烦，如果单机挂掉，轨迹数据就会丢失。</p><p>以上是从成本角度考虑的。前面我们讲过消息轨迹虽然很重要，但漏记是允许的，只要保证大部分情况下能用就行，允许短时间不可用。</p><p>从使用者的角度，如果查询的频率较低，投入很多成本，从 ROI 来看收益不高。所以一些系统在设计时，就会考虑复用单机的存储和检索能力。比如每台 Broker 部署一个 RocksDB 服务，数据存储到每台 Broker 的 RocksDB 上，需要检索的时候，依次访问每台 Broker 上的服务去查询消息。</p><p>总的来说，四种方案都有人用，选择的依据在于对成本和可靠性的考量。第一、二种用得比较多，比如 RocketMQ 和 RabbitMQ 就是用的第二种。</p><p>我个人也推荐内置主题的形式，因为复用了消息队列的缓冲和存储的能力，性能较高，也适合远程的分布式采集。最主要的是不依赖第三方系统，在私有化部署或者独立部署的过程中，可以完成组件内的闭环。</p><h3 id="持久存储引擎的选择" tabindex="-1">持久存储引擎的选择 <a class="header-anchor" href="#持久存储引擎的选择" aria-label="Permalink to &quot;持久存储引擎的选择&quot;">​</a></h3><p>持久存储引擎存在的意义就是高可靠、长期地保存轨迹数据，并提供所需要的数据检索能力。所以对于引擎，我们有三个要求：数据不能丢、能长期保留数据、具备检索能力。</p><p>业界主流的存储引擎有不少。从数据可靠性来看，这些引擎都具备高可靠存储的能力，也具备长期保留数据的能力。因为消息轨迹在检索方面的需求相对比较固定，主要是根据消息 ID 或时间 + 消息 ID 进行精准查询，基本所有的存储引擎都可能满足条件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/6.jpeg" alt=""></a></p><p>那一般怎么选呢？你可能会想，很简单啊，选 ElasticSearch，ES 本身就是很强大且通用的搜索引擎，访问方便、性能也很高、检索能力强大。</p><p>回答是没错的，大部分情况下，我们的选择都是用 ES。但是 ES 的缺点也很明显，我们前面说了它的存储放大严重，很占磁盘空间，会导致成本较高。</p><p>在我看来，除了技术上的功能、性能层面的选择，成本也是一个非常重要的因素。因为在大规模集群的消息轨迹的架构设计中，成本是一个非常重要的选项。如果业务流量较低、轨迹数据较少，用 ES 很合适，因为功能和性能都满足要求，成本也不会有太大压力。</p><p>但是，在大规模的集群（比如几万台节点）运营中，我们更多在权衡的不是功能和性能，而是如何在功能、性能、稳定性、成本四个点之间取得平衡。思考的路径一般是可以牺牲一部分的功能、性能或稳定性，在满足基本需求的基础上，尽量降低成本。</p><p>而且因为数据规模不同，公司常用存储引擎不一样，也有的会用 ClickHouse、HBase 等引擎存储轨迹数据。从消息轨迹的业务上来看，功能都是满足的，从成本来看，主要看数据规模。所以，在引擎选择上，并没有定性的结论，但是 ES 还是最普遍的。</p><h2 id="rabbitmq-消息轨迹方案设计实操" tabindex="-1">RabbitMQ 消息轨迹方案设计实操 <a class="header-anchor" href="#rabbitmq-消息轨迹方案设计实操" aria-label="Permalink to &quot;RabbitMQ 消息轨迹方案设计实操&quot;">​</a></h2><p>了解了具体的技术选型，我们回过头看 RabbitMQ 消息轨迹的案例，我分享一下我的方案和思考点，整体流程分为五步。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/7.jpeg" alt=""></a></p><ol><li><p>存储引擎选择：消息查询需要支持多维度查询和模糊查询，只有几百个节点且主要承载业务消息，所以整体的轨迹数据量预期不会太大，加上成本限制不是特别严重，我会选择 ES 当存储引擎。</p></li><li><p>客户端轨迹记录：RabbitMQ 无法记录客户端（Produce 和 Consumer）的轨迹，我会单独提供一套 SDK 实现集成轨迹的发送逻辑，把数据发送到 RabbitMQ 集群中的amq.rabbitmq.trace 中。</p></li><li><p>服务端轨迹记录：RabbitMQ 内核已经实现了轨迹的功能。只要打开 Trace 开关，就能把生产接收的时间和消费拉取的时间等数据写入到名为 amq.rabbitmq.trace 的 Exchange 中，无需重复开发。</p></li><li><p>实现轨迹数据存储：当记录完轨迹后，我们可以开发一个客户端去消费集群中的 TraceQueue，消费完数据往 ES 存储。</p></li><li><p>轨迹查询：轨迹查询平台查询轨迹的时候，直接通过 HTTP Rest 访问 ES 的接口查询轨迹数据即可。</p></li></ol><p>这个方案比较简单务实。不过 RabbitMQ 的 Queue 堆积太多数据，可能会造成集群压力较大，导致不稳定。</p><p>所以如果想在“实现轨迹数据存储”这一步保证消费的性能，你也可以直接把数据写入到本地文件，然后通过 Filebeat、Fluend 等采集器把数据采集到 ES。这种方案相比直接发送 ES，消费速度更快，Trace Queue 基本不会有堆积。</p><h2 id="分享一个大集群的实际案例" tabindex="-1">分享一个大集群的实际案例 <a class="header-anchor" href="#分享一个大集群的实际案例" aria-label="Permalink to &quot;分享一个大集群的实际案例&quot;">​</a></h2><p>RabbitMQ 的方案设计，集群比较小，我们实际工作时集群规模都比较大，所以这里我也想分享一个对应的实际案例，蛮实用的，也很有意思。</p><p>我们在现网大规模集群的轨迹架构中，因为节点数非常多，轨迹数据非常大，全部集群数据加起来接近 PB 级，如果存储到 ES 进行查询，成本会爆炸。</p><p>为了极限降低成本，我们曾经实现一个内部的消息轨迹查询功能。用的是服务端保存轨迹数据的第四种方案，把轨迹数据写入到本地文件，按时间分段存储，配置了本地文件的清理策略，比如只保留最近十天，然后在节点上起一个 HTTP Server，接收轨迹关键字比如轨迹 ID，最后通过执行 Linux 原生的 grep 命令检索本地文件，查询起来性能还是可以的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/22/8.jpeg" alt=""></a></p><p>这个方案因为利用了 Linux 原生的 grep 字符串匹配能力，加上一般情况下，消息队列 Broker的本地磁盘容量都会有一定的冗余，所以几乎零成本实现了消息轨迹。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>消息轨迹记录了消息从生产到消费完成或消费失败的整个生命周期。从轨迹中，可以看到生产时间、服务端收到数据的时间，进入延时队列、消费成功或者进入死信队列时间等等。有了消息轨迹，我们就可以完美定位消息丢失的问题。</p><p>在小规模集群的运营过程中，将 ES 当做存储引擎是比较常用的方案。在数据非常少的场景中，有时候 MySQL 也可以当作存储引擎。业界的 ClickHouse、HBase 也可以作为存储引擎的备选方案。</p><p>在大规模的集群运营中，从方案选择上来看，不能只关注技术层面的功能和性能，更重要的是需要关注成本。如果成本非常严苛，可以选择适当牺牲功能和性能，以降低成本。有时候适当牺牲，可以降低相当大比例的成本。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在 RabbitMQ 的消息轨迹方案设计中，如果调整 1 和 5 的条件，数据量变为非常大，而成本需要尽量控制，你会如何设计方案呢？</p><p>欢迎分享你的方案和思考，如果觉得有收获，也欢迎你把这节课分享给感兴趣的朋友。我们下节课再见！</p><h2 id="上节课思考闭环" tabindex="-1">上节课思考闭环 <a class="header-anchor" href="#上节课思考闭环" aria-label="Permalink to &quot;上节课思考闭环&quot;">​</a></h2><p>如果让你在当前主要维护的一个服务中实现透明监控，你会怎么做？</p><p>首先，我会调研一下公司当前有没有团队实现过现类似的透明监控，然后调研一下当前团队和公司有的监控系统是基于什么实现的。考虑这个点是因为，希望能够和公司已有的监控体够尽量贴合，以减少后续独立开发维护的成本。</p><p>如果是独立的一个模块，并且公司已经有了 Prometheus 服务，我会建你议用 Prometheus 的全套方案，利用 Peometheus 数据类型注册指、内置 HTTP Server 暴露 /Metrics 的方式提供数据。这种方式的好处就是简单方便，实现成本低。</p><p>如果是一个全新的大项目，包含多个组件，我建议你用 OpenTelemetry 的方案。从长期来看，OpenTelemetry 在完整度和可维护性上会更优雅。</p>',94)])])}const u=t(p,[["render",s]]);export{b as __pageData,u as default};
